local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local decodeMap = {}
for i = 1, #alphabet do
    decodeMap[string.sub(alphabet, i, i)] = i - 1
end

local function decodeBase64(s)
    s = s:gsub("%s+", "")
    local out = {}
    local outLen = 0
    local buffer = 0
    local bits = 0

    for i = 1, #s do
        local ch = string.sub(s, i, i)
        if ch ~= "=" then
            local v = decodeMap[ch]
            if v then
                buffer = buffer * 64 + v
                bits = bits + 6
                if bits >= 8 then
                    bits = bits - 8
                    local byte = math.floor(buffer / (2 ^ bits)) % 256
                    outLen += 1
                    out[outLen] = string.char(byte)
                    buffer = buffer % (2 ^ bits)
                end
            end
        end
    end

    return table.concat(out)
end

local raw = decodeBase64(BASE64)
local data = buffer.fromstring(raw)

local ok, instances = pcall(function()
    return SerializationService:DeserializeInstancesAsync(data)
end)

if not ok then
    error("RBXM deserialize failed: " .. tostring(instances))
end

-- =========================================================
-- GENERIC RBXM INSERT LOGIC
-- =========================================================
-- The RBXM has already been decoded/deserialized above.
-- InsertAsset() can be called for this embedded asset.
--
-- If you use a server-backed system of your own, set:
--   LoadAssetRemote
--   ClearAssetRemote
--   PlayerGui
-- and use the remote branch below.
-- Otherwise, this file inserts the already-deserialized
-- Instances directly into Workspace.

local function InsertAsset(assetName, statusTarget)
    assetName = tostring(assetName or "rod_fish_it"):gsub("%.rbxm$", "")

    local function setStatus(text)
        if statusTarget then
            pcall(function()
                statusTarget.Text = text
            end)
        end
    end

    setStatus("Working")

    -- Server-backed path for a server you control.
    local remote = rawget(_G, "LoadAssetRemote")
    local clearRemote = rawget(_G, "ClearAssetRemote")
    local playerGui = rawget(_G, "PlayerGui")

    if remote and remote:IsA("RemoteFunction") and playerGui then
        local ok, result = pcall(function()
            return remote:InvokeServer(assetName)
        end)

        if not ok or not result then
            setStatus("Gagal")
            return false, result or "Server request failed"
        end

        local serverFolder = playerGui:WaitForChild(assetName, 10)
        if not serverFolder then
            setStatus("No Asset")
            return false, "Server asset was not returned"
        end

        local clone = serverFolder:Clone()
        local children = clone:GetChildren()

        if #children == 0 then
            clone:Destroy()
            setStatus("Empty")
            return false, "Asset is empty"
        end

        local count = 0
        for _, obj in ipairs(children) do
            obj.Parent = Workspace
            count += 1
        end

        clone:Destroy()

        if clearRemote and clearRemote:IsA("RemoteFunction") then
            pcall(function()
                clearRemote:InvokeServer(assetName)
            end)
        end

        setStatus("Inserted: " .. count)
        return true, count
    end

    -- Local fallback: use the embedded RBXM data.
    local insertedCount = 0

    for _, instance in ipairs(instances) do
        if instance and instance.Parent == nil then
            instance.Parent = Workspace
            insertedCount += 1
        end
    end

    if insertedCount == 0 then
        setStatus("Already Inserted")
        return false, "No unparented root instances available"
    end

    setStatus("Inserted: " .. insertedCount)
    return true, insertedCount
end

